contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept parameters to drive the property: amount to wager and a flag to open the contract.
    function run(uint256 openFlag, uint256 amount) public payable {
        // ensure this test contract has enough ETH if it will send value to c
        require(address(this).balance >= amount);

        // Only the owner of C can open to public. Since the checker deploys a fresh C and
        // passes it into this test's constructor, this test contract is the deployer and thus owner.
        if (openFlag % 2 == 1) {
            // call OpenToThePublic as owner
            c.OpenToThePublic();
        }

        // Adjust bet limit to the provided amount so wager() will require msg.value == betLimit
        c.AdjustBetAmounts(amount);

        // Record balance before
        uint256 beforeBalance = address(c).balance;
        bool reverted;

        // Attempt to wager by sending `amount` wei. Catch reverts to observe outcome.
        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after the attempt
        uint256 afterBalance = address(c).balance;
        bool playerMarked = c.hasPlayerWagered(address(this));

        // General rule: if the wager call did NOT revert then (1) contract balance increased by amount
        // and (2) hasPlayerWagered returns true; conversely if it reverted then neither holds.
        // We express this as equivalence: (not reverted) iff (balance increased by amount AND playerMarked)
        assert((!reverted) == ((afterBalance == beforeBalance + amount) && playerMarked));
    }

    receive() external payable {}
}

