contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that drives the contract
    // params: openFlag to open contract, setLimit to set bet limit, seedAmount sent to wager (must equal bet limit)
    function run(uint256 openFlag, uint256 setLimit, uint256 seedAmount) public payable {
        // ensure this test contract has enough ETH to send the wager and possible donate/lose flows
        require(address(this).balance >= seedAmount);

        // 1) Make contract open if requested
        if (openFlag % 2 == 1) {
            c.OpenToThePublic();
        }

        // 2) Set bet limit to setLimit so wager requires that amount
        c.AdjustBetAmounts(setLimit);

        // 3) Ensure betLimit equals seedAmount by setting setLimit == seedAmount externally when calling run.
        // Try to place a wager sending seedAmount; observe whether it reverts
        bool wagerReverted;
        try c.wager{value: seedAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Record observable state before calling play
        uint256 balanceBefore = address(c).balance;
        uint256 winnersPotBefore = c.winnersPot();
        bool hasWager = c.hasPlayerWagered(address(this));

        // Attempt to play and observe whether it reverts
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Read observable state after play
        uint256 balanceAfter = address(c).balance;
        uint256 winnersPotAfter = c.winnersPot();

        // General property:
        // If play succeeded (did not revert) then either the contract paid out a winner (winnersPot decreased)
        // or the contract sent at most betLimit/2 to whale (balance decreased by at most betLimit/2).
        // If play reverted then nothing is required by this rule (it may revert for timing or preconditions).
        assert(playReverted || (
            // play succeeded
            (
                // either winnersPot decreased (some payout to winner)
                winnersPotAfter <= winnersPotBefore
            ) && (
                // and the total balance did not decrease by more than betLimit/2
                balanceBefore >= balanceAfter && (balanceBefore - balanceAfter) <= (c.currentBetLimit() / 2 + winnersPotBefore - winnersPotAfter + 0)
            )
        ));
    }

    // allow receiving ETH forwarded from c
    receive() external payable {}
}

