        c.AdjustBetAmounts(setLimit);

        // Try to place a wager by sending stake (must equal bet limit to succeed)
        bool wagerReverted;
        try c.wager{value: stake}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Observe pre-play values (views only)
        uint256 balanceBefore = address(c).balance;
        uint256 winnersPotBefore = c.winnersPot();
        bool hasWagerBefore = c.hasPlayerWagered(address(this));
        uint256 betLimitNow = c.currentBetLimit();

        // Attempt to play
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Observe post-play values
        uint256 balanceAfter = address(c).balance;
        uint256 winnersPotAfter = c.winnersPot();

        // General invariant/assertion (single assert):
        // If play reverted then no guarantee; if play succeeded then it must have been callable
        // only when the test contract had a wager (hasWagerBefore==true), and either winnersPot decreased
        // (a payout happened) or the contract's balance decreased by at most betLimit/2 (lose path).
        assert(
            playReverted || (
                hasWagerBefore && (
                    (winnersPotAfter < winnersPotBefore) || (balanceBefore >= balanceAfter && (balanceBefore - balanceAfter) <= (betLimitNow / 2))
                )
            )
        );
