contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to open to public as owner (constructor deployer of C was this test contract),
    // then attempt to wager with a provided amount equal to currentBetLimit.
    // The property: if wager succeeds then hasPlayerWagered(address(this)) == true and ethBalance increased by amount;
    // if wager reverts then hasPlayerWagered stays false and ethBalance unchanged.

    function run(uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for test");
        // Ensure c is open to public by calling OpenToThePublic from owner (this contract is owner)
        c.OpenToThePublic();

        uint256 beforeBalance = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 betLimit = c.currentBetLimit();

        // We will try to wager with either the exact betLimit or a different amount depending on input.
        // Use try/catch to detect revert.
        bool reverted;
        if (sendAmount == betLimit) {
            // attempt valid wager by sending exact amount
            try c.wager{value: sendAmount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // attempt invalid wager (wrong amount) which should revert
            try c.wager{value: sendAmount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule: if the call did not revert then hasPlayerWagered must be true and contract balance increased by sendAmount;
        // if it reverted then hasPlayerWagered must remain as before and balance unchanged.
        assert(
            (!reverted && afterHas == true && afterBalance == beforeBalance + sendAmount)
            || (reverted && afterHas == beforeHas && afterBalance == beforeBalance)
        );
    }

    // Allow receiving ETH so the test contract can fund wagers
    receive() external payable {}
}

