contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to control betLimit and donate/play behavior
    // amount must equal the current betLimit to make wager succeed.
    function run(address whaleAddr, uint256 wagerAmount) public payable {
        // ensure this contract has enough Ether to send wagers/donations
        require(address(this).balance >= wagerAmount);

        // 1) Open contract to public as owner (constructor of c set owner to deployer which is this test contract)
        c.OpenToThePublic();

        // 2) Optionally adjust bet limit so that wagerAmount equals the bet limit
        //    We call AdjustBetAmounts as owner (this contract is owner) to set limit
        c.AdjustBetAmounts(wagerAmount);

        // Read pre-state
        uint256 beforeWinnersPot = c.winnersPot();
        uint256 beforeBalance = address(c).balance;
        bool beforeHasWager = c.hasPlayerWagered(address(this));

        // 3) Place the wager by sending exactly wagerAmount
        //    This must be a top-level state-changing call
        c.wager{value: wagerAmount}();

        // After wager, the player must be registered as having wagered
        bool afterWagerHas = c.hasPlayerWagered(address(this));
        // winnersPot should not increase because wager only sets internal mappings
        uint256 afterWagerWinnersPot = c.winnersPot();

        // 4) Now attempt to play. play may revert if block conditions fail; capture that.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Read post-state
        bool afterPlayHas = c.hasPlayerWagered(address(this));
        uint256 afterBalance = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot();

        // General rule asserted:
        // If play reverted then the wagered status must still be true (player remains a player)
        // If play did not revert then the wagered status must have been cleared (player no longer a player)
        // Additionally, if play succeeded then the winnersPot (which is half of contract balance) cannot have increased
        // compared to the moment right after wagering (payout transfers out ETH or leaves same); thus afterWinnersPot <= afterWagerWinnersPot
        assert(
            (playReverted && afterPlayHas) ||
            (!playReverted && !afterPlayHas && afterWinnersPot <= afterWagerWinnersPot)
        );
    }

    // allow receiving refunded or transferred Ether if needed
    receive() external payable {}
}

