        require(difficulty > 0);

        // Make contract open to public and set bet limit and difficulty
        c.OpenToThePublic();
        c.AdjustBetAmounts(betAmount);
        c.AdjustDifficulty(difficulty);

        // Ensure this test contract holds enough ETH to place the wager if betAmount > 0
        if (betAmount > 0) {
            require(address(this).balance >= betAmount);
            // Place a wager with exactly betAmount
            c.wager{value: betAmount}();
        } else {
            // If betAmount == 0, still call wager (it will require msg.value == betLimit == 0)
            c.wager{value: 0}();
        }

        // Confirm the player had a wager recorded before calling play (observable)
        bool hadWager = c.hasPlayerWagered(address(this));

        // Attempt to play and record whether it reverted
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the play attempt, the player's wagered status must be false if the call did not revert,
        // or may be unchanged if it reverted. Thus: reverted || (hasPlayerWagered == false)
        bool afterWager = c.hasPlayerWagered(address(this));

        assert(reverted || afterWager == false);
    }

    // Allow receiving Ether (payouts, donated forwards, etc.)
