contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to send Ether to c when calling wager, so this function is payable
    // Inputs: whale address and initial wagerLimit are already set in deployed C; here we take amount to send
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Precondition: open the contract to public so wager can be called
        // Only owner can call OpenToThePublic; the deploying owner of C is msg.sender of C's constructor,
        // which (per problem) is the test deployer; but in the checker setup InvMutTest deployed C,
        // so InvMutTest is the owner. Thus InvMutTest can call OpenToThePublic.
        c.OpenToThePublic();

        // Read before values
        uint256 beforeBalance = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 currentBetLimit = c.currentBetLimit();

        // Only try to wager when amount equals bet limit — otherwise the call will revert.
        bool reverted;
        if (amount == currentBetLimit) {
            // Ensure we send exactly amount
            try c.wager{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If amount != bet limit, attempt would revert; simulate that by not calling and setting reverted true
            reverted = true;
        }

        // Read after values
        uint256 afterBalance = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule: if the wager call did not revert and amount equals the bet limit then
        // hasPlayerWagered must have become true and contract balance must have increased by exactly amount.
        // Conversely, if amount != bet limit then the call must have reverted (we model that above).
        assert(((amount == currentBetLimit && reverted == false) -> (afterHas == true && afterBalance == beforeBalance + amount))
               && ((amount != currentBetLimit) -> (reverted == true)));
    }

    // receive to accept refunds/transfers if any
    receive() external payable {}
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to send Ether to c when calling wager, so this function is payable
    // amount is the Ether we will attempt to wager
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Open the contract to the public so wager can be invoked
        c.OpenToThePublic();

        // Read pre-state
        uint256 beforeBalance = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 currentBetLimit = c.currentBetLimit();

        bool calledAndSucceeded = false;
        bool reverted;

        // Only attempt the call when amount equals currentBetLimit, otherwise calling would revert
        if (amount == currentBetLimit) {
            try c.wager{value: amount}() {
                reverted = false;
                calledAndSucceeded = true;
            } catch {
                reverted = true;
                calledAndSucceeded = false;
            }
        } else {
            // If we don't match the bet limit, an attempt would revert. We model this by not calling and marking reverted=true.
            reverted = true;
            calledAndSucceeded = false;
        }

        // Read post-state
        uint256 afterBalance = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // Assert the general property:
        // - If we called with exact bet limit and it succeeded, then hasPlayerWagered became true and balance increased by amount.
        // - If amount != currentBetLimit then the call must have reverted (we represent this by reverted==true).
        // Note: written without implication operator to be compatible with Solidity asserts.
        assert(
            (calledAndSucceeded == true && reverted == false && amount == currentBetLimit && afterHas == true && afterBalance == beforeBalance + amount)
            ||
            (amount != currentBetLimit && reverted == true)
        );
    }

    receive() external payable {}
}

