    // Parameters:
    // - open: whether to open the contract to public first
    // - setBetLimit: set bet limit before wagering (owner-only, this contract is owner)
    // We fund this contract externally when running the test so it can send the wager amount.
    function run(bool open, uint256 setBetLimit) public payable {
