        // Observe before-state
        uint256 beforeBal = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 beforeWinnersPot = c.winnersPot();

        // Place the wager (must be a top-level state-changing call)
        bool wagerReverted;
        try c.wager{value: setBetLimit}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // If wager reverted, we cannot proceed to play (play would revert due to onlyPlayers), so assert that nothing changed
        if (wagerReverted) {
            uint256 afterBal1 = address(c).balance;
            bool afterHas1 = c.hasPlayerWagered(address(this));
            uint256 afterWinnersPot1 = c.winnersPot();
            assert(afterBal1 == beforeBal && afterHas1 == beforeHas && afterWinnersPot1 == beforeWinnersPot);
            return;
        }

        // Now we must call play(); capture whether it reverts
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Read after-state
        uint256 afterBal = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));
        uint256 afterWinnersPot = c.winnersPot();

        // General rule:
        // If play did NOT revert, the player's wager must have been cleared (hasPlayerWagered false)
        // and the contract balance must have decreased by either setBetLimit/2 (lose case) or by beforeWinnersPot (payout case).
        // If play reverted, state should be unchanged from right after successful wager placement.
        if (!playReverted) {
            // compute the two allowed decreases without underflow
            uint256 loseDecrease = setBetLimit / 2;
            uint256 payoutDecrease = beforeWinnersPot;
            bool decreasedByLose = (beforeBal >= afterBal) && (beforeBal - afterBal == loseDecrease);
            bool decreasedByPayout = (beforeBal >= afterBal) && (beforeBal - afterBal == payoutDecrease);
            assert(afterHas == false && (decreasedByLose || decreasedByPayout));
        } else {
            // play reverted: nothing should have changed compared to state immediately after wager
            // after a successful wager, contract balance increased by setBetLimit and hasPlayerWagered is true
            // So check that after state matches that expectation
            uint256 expectedBal = beforeBal + setBetLimit;
            bool expectedHas = true;
            assert(afterBal == expectedBal && afterHas == expectedHas);
        }
    }

    // allow receiving Ether so this test contract can fund wagers
    receive() external payable {}
}

