contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call OpenToThePublic as owner first; the deployer of c is the owner,
    // but here msg.sender is this contract. To make this contract the owner,
    // the test harness deploys c and passes it in; the checker ensures c was freshly deployed
    // with owner = deployer (the harness), so we cannot assume we are owner.
    // Therefore, instead we require that the caller of run is the owner of c by
    // opening to public via a try/catch on OpenToThePublic; if that reverts,
    // we proceed only if we can still observe betLimit and call wager should revert.

    // Single public function with parameters: amount to send and a flag whether
    // we attempt to open to public (owner-only). We take amount and will send it to wager.
    function run(uint256 amount, bool tryOpen) public payable {
        require(true);

        // Record before values
        uint256 beforeBalance = address(c).balance;
        uint256 betLimit = c.currentBetLimit();
        bool beforeHas = c.hasPlayerWagered(address(this));

        // If requested, attempt to open to public. It may revert if not owner; catch that.
        bool opened;
        if (tryOpen) {
            try c.OpenToThePublic() {
                opened = true;
            } catch {
                opened = false;
            }
        } else {
            opened = false;
        }

        // To call wager we must send exactly betLimit. Ensure we have funds if needed.
        // If amount != betLimit then the call should revert. We'll attempt the call and record revert.
        bool reverted;
        // Ensure this contract has enough balance to send 'amount'
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        try c.wager{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // ASSERTION: If the contract was open to public (either we successfully opened it or it already was open)
        // and we sent exactly the current betLimit and we were not a player before,
        // then wager must succeed (not reverted), after which hasPlayerWagered is true and contract balance increased by exactly amount.
        // We cannot directly observe whether it was already open except via trying wager: but c.wager will revert when not open.
        // So the condition uses opened OR that the wager did not revert while matching betLimit and not a prior player.

        // Build the implication antecedent:
        bool antecedent = (!beforeHas) && (amount == betLimit) && (!reverted ? true : opened);
        // If antecedent holds, enforce consequent:
        // consequent: reverted == false, afterHas == true, afterBalance == beforeBalance + amount
        assert(!antecedent || (reverted == false && afterHas == true && afterBalance == beforeBalance + amount));
    }

    // Allow contract to receive ETH funding from the test harness if needed
    receive() external payable {}
}

